const visionText = $json.text;
const caption = $('Telegram Trigger').item.json.message.caption || '';
const foodDescription = caption ? (visionText + '. User caption: ' + caption) : visionText;
return [{ json: { foodDescription } }];

const items = $input.all().map(i => i.json);
const messageItem = items.find(i => i.foodDescription !== undefined) || { foodDescription: '' };
const foodDb = items.filter(i => i['Food ID'] !== undefined);
const goalsRows = items.filter(i => i['Day'] !== undefined && i['Calories'] !== undefined && i['Food ID'] === undefined);

const today = $now.setZone('Asia/Kolkata').toFormat('cccc');
const goalRow = goalsRows.find(r => r.Day === today) || {};
const targetLine = 'Calories ' + goalRow.Calories + ', Protein ' + goalRow.Protein + 'g, Carbs ' + goalRow.Carbs + 'g, Fats ' + goalRow.Fats + 'g';
const foodList = foodDb.map(f => [f['Food ID'], f['Food name'], f['Serving size'], f['Calories'], f['Protein'], f['Carbs'], f['Fats']].join('|')).join('\n');

return [{ json: { foodDescription: messageItem.foodDescription, foodList, targetLine } }];
